import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;
    function setUp() public {
        c = new C();
        owner = c.Owner();
    }
    function testFuzz_property(address adr, bytes memory data, address actor, uint256 amount) public {
        // admissible domain: ensure the actor is not the owner and adr is not this test contract
        vm.assume(actor != owner);
        vm.assume(adr != address(c));
        vm.assume(adr != address(this));
        // fund the contract via the owner so there is balance to steal
        vm.deal(owner, amount);
        vm.prank(owner);
        (bool ok1,) = address(c).call{value: amount}("");
        require(ok1, "fund failed");
        uint256 balanceBefore = owner.balance;
        // drive Command as the non-owner actor
        vm.assume(amount <= address(c).balance);
        vm.deal(actor, amount);
        vm.prank(actor);
        try c.Command(adr, data) { }
        catch { }
        // now call withdraw as the non-owner actor (should revert in reference, succeed in bug)
        vm.deal(actor, amount);
        vm.prank(actor);
        bool reverted = false;
        try c.withdraw() { }
        catch { reverted = true; }
        uint256 balanceAfter = owner.balance;
        // general rule: if withdraw did not revert, owner's balance must not have decreased
        assertTrue(reverted || balanceAfter >= balanceBefore);
    }
