pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 withdrawAmount) public {
        // 1. Bound to admissible domain: balance must cover withdraw, and withdraw <= balance
        initialBalance = bound(initialBalance, 1, type(uint256).max / 2);
        withdrawAmount = bound(withdrawAmount, 1, initialBalance);

        // 2. Setup: fund contract with initialBalance
        vm.deal(address(c), initialBalance);

        // Owner is this contract (msg.sender at deploy). Call withdraw.
        uint256 balanceBefore = address(c).balance;
        c.withdraw();
        uint256 balanceAfter = address(c).balance;

        // 3. Assert: balance must strictly decrease by the amount transferred (which is the entire pre-withdraw balance)
        // For the reference, balanceAfter must be 0 and balanceBefore > 0.
        // The buggy version leaves balance unchanged, so balanceAfter == balanceBefore, breaking the strict inequality.
        assertTrue(balanceAfter < balanceBefore);
    }
}

