        // Restrict adr to a reasonable call target (not owner, to force a difference)
        vm.assume(adr != owner);
        // Ensure the amount does not exceed what we can fund
        vm.assume(amount <= type(uint120).max);

        // Fund the test contract with enough ETH for the call value
        vm.deal(owner, amount + 1 ether);

        // Record owner's balance before the call
        uint256 ownerBalanceBefore = owner.balance;

        // Owner calls Command
        vm.prank(owner);
        (bool success,) = address(c).call{value: amount}(abi.encodeWithSignature("Command(address,bytes)", adr, data));
        require(success, "Command call failed");

        uint256 ownerBalanceAfter = owner.balance;

        // If data encodes a value transfer back to owner (e.g., via a contract that selfdestructs to owner),
        // both versions would increase owner's balance; however, in the reference the call is made to adr,
        // so the owner balance change depends on adr's behavior. In the buggy version, the call is made to owner,
        // meaning the owner sends ETH to itself (balance change is just -gas).
        // The universal property: Owner's ETH balance after Command cannot be strictly greater than before minus the value sent,
        // because the reference sends value to adr, and any return to owner is from adr. The bug sends value to owner (self-call),
        // which can artificially increase owner's balance (if the low-level call to owner with value does not revert) without
        // adr's involvement.
        assertTrue(ownerBalanceAfter <= ownerBalanceBefore - amount, "Owner balance must not increase beyond sent value");
    }
}

